use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};
use serde::Deserialize;

use crate::DEFAULT_PORT;

#[derive(Debug, Clone, Deserialize, Default)]
#[serde(deny_unknown_fields)]
pub struct ClientConfig {
    pub network: Option<String>,
    pub secret: Option<String>,
    pub server: Option<String>,
    pub port: Option<u16>,
    pub tcp_port: Option<u16>,
    pub identity: Option<PathBuf>,
    pub room: Option<String>,
    pub password: Option<String>,
    pub nickname: Option<String>,
    pub create_room: Option<bool>,
    /// Validation file generated by `ara-server gen-access`.
    pub access: Option<PathBuf>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct AccessFile {
    pub server: String,
    #[serde(default)]
    pub token: String,
    #[serde(default)]
    pub name: String,
    /// Server X25519 public key used for the DH challenge.
    #[serde(default)]
    pub server_pub: String,
}

impl ClientConfig {
    pub fn from_file(path: &Path) -> Result<Self> {
        let text = std::fs::read_to_string(path)
            .with_context(|| format!("read config {}", path.display()))?;
        toml::from_str(&text).context("parse config TOML")
    }

    /// CLI values override file values.
    #[allow(clippy::too_many_arguments)]
    pub fn merge_cli(
        mut self,
        network: Option<String>,
        secret: Option<String>,
        server: Option<String>,
        port: Option<u16>,
        tcp_port: Option<u16>,
        identity: Option<PathBuf>,
        room: Option<String>,
        password: Option<String>,
        nickname: Option<String>,
        create_room: bool,
        access: Option<PathBuf>,
    ) -> Self {
        self.network = network.or(self.network);
        self.secret = secret.or(self.secret);
        self.server = server.or(self.server);
        self.port = port.or(self.port);
        self.tcp_port = tcp_port.or(self.tcp_port);
        self.identity = identity.or(self.identity);
        self.room = room.or(self.room);
        self.password = password.or(self.password);
        self.nickname = nickname.or(self.nickname);
        if create_room {
            self.create_room = Some(true);
        }
        self.access = access.or(self.access);
        self
    }

    pub fn validate(self) -> Result<ResolvedConfig> {
        let access = match &self.access {
            Some(path) => Some(
                serde_json::from_str::<AccessFile>(
                    &std::fs::read_to_string(path)
                        .with_context(|| format!("read access file {}", path.display()))?,
                )
                .context("parse access file")?,
            ),
            None => None,
        };
        let server = access
            .as_ref()
            .map(|a| a.server.clone())
            .or(self.server)
            .context("missing 'server' (or an --access file)")?;
        let network = self.network.unwrap_or_default();
        let secret = self.secret.unwrap_or_default();
        let room_code = self.room.unwrap_or_else(|| network.clone());
        let room_password = self.password.unwrap_or_else(|| secret.clone());
        let create_room = self.create_room.unwrap_or(false);
        if room_code.is_empty() && !create_room {
            bail!("missing room code (or --create)");
        }
        if room_code.is_empty() && room_password.is_empty() {
            bail!("creating a room requires --password");
        }
        let (server_host, server_port) = match server.rsplit_once(':') {
            Some((h, p)) => (h.to_string(), p.parse().context("server port")?),
            None => (server.clone(), DEFAULT_PORT),
        };
        Ok(ResolvedConfig {
            network,
            secret,
            server_host,
            server_port,
            local_port: self.port.unwrap_or(DEFAULT_PORT),
            tcp_port: self.tcp_port.unwrap_or_else(|| self.port.unwrap_or(DEFAULT_PORT)),
            identity_path: self.identity,
            room_code,
            room_password,
            access_token: access.as_ref().map(|a| a.token.clone()).unwrap_or_default(),
            server_pub: access.as_ref().map(|a| a.server_pub.clone()).unwrap_or_default(),
            nickname: self.nickname.unwrap_or_default(),
            create_room,
            direct_peer_addr: None,
            direct_peer_key: String::new(),
            direct_peer_vip: None,
            direct_vip: None,
        })
    }
}

#[derive(Debug, Clone)]
pub struct ResolvedConfig {
    pub network: String,
    pub secret: String,
    pub server_host: String,
    pub server_port: u16,
    /// Local UDP port shared by STUN and WireGuard; 0 = ephemeral.
    pub local_port: u16,
    /// Local TCP port for the direct-TCP fallback transport.
    pub tcp_port: u16,
    /// Override identity key file (default: per-user platform path).
    pub identity_path: Option<PathBuf>,
    /// M3 room code; empty with `create_room` means "create a new room".
    pub room_code: String,
    pub room_password: String,
    pub access_token: String,
    /// Server public key for the DH challenge (empty = legacy server).
    pub server_pub: String,
    pub nickname: String,
    pub create_room: bool,
    /// Offline direct mode: peer address, peer public key, peer VIP, own VIP.
    pub direct_peer_addr: Option<std::net::SocketAddr>,
    pub direct_peer_key: String,
    pub direct_peer_vip: Option<std::net::Ipv4Addr>,
    pub direct_vip: Option<std::net::Ipv4Addr>,
}

#[cfg(test)]
mod tests {
    use super::*;

    fn base() -> ClientConfig {
        ClientConfig {
            network: Some("n".into()),
            secret: Some("s".into()),
            server: Some("1.1.1.1".into()),
            ..Default::default()
        }
    }

    #[test]
    fn cli_overrides_file() {
        let file = ClientConfig {
            network: Some("file-net".into()),
            secret: Some("file-secret".into()),
            server: Some("1.1.1.1".into()),
            port: Some(1),
            ..Default::default()
        };
        let merged = file.merge_cli(
            Some("cli-net".into()),
            None,
            None,
            Some(2),
            None,
            None,
            None,
            None,
            None,
            false,
            None,
        );
        let r = merged.validate().unwrap();
        assert_eq!(r.room_code, "cli-net");
        assert_eq!(r.room_password, "file-secret");
        assert_eq!(r.local_port, 2);
        assert_eq!(r.server_host, "1.1.1.1");
        assert_eq!(r.server_port, DEFAULT_PORT);
    }

    #[test]
    fn server_host_port_split() {
        let c = ClientConfig {
            server: Some("example.com:9999".into()),
            ..base()
        };
        let r = c.validate().unwrap();
        assert_eq!(r.server_host, "example.com");
        assert_eq!(r.server_port, 9999);
    }

    #[test]
    fn missing_fields_fail() {
        assert!(ClientConfig::default().validate().is_err());
    }

    #[test]
    fn default_port() {
        let c = ClientConfig { port: None, ..base() };
        assert_eq!(c.validate().unwrap().local_port, DEFAULT_PORT);
    }

    #[test]
    fn room_mode_reads_password() {
        let c = ClientConfig {
            room: Some("ABC123".into()),
            password: Some("pw".into()),
            ..base()
        };
        let r = c.validate().unwrap();
        assert_eq!(r.room_code, "ABC123");
        assert_eq!(r.room_password, "pw");
        assert!(!r.create_room);
    }

    #[test]
    fn create_room_requires_password() {
        let c = ClientConfig {
            create_room: Some(true),
            room: None,
            network: None,
            secret: None,
            ..base()
        };
        assert!(c.validate().is_err());
        let c = ClientConfig {
            create_room: Some(true),
            password: Some("pw".into()),
            network: None,
            secret: None,
            ..base()
        };
        assert!(c.validate().unwrap().create_room);
    }

    #[test]
    fn access_file_provides_server_and_token() {
        let dir = std::env::temp_dir().join(format!("ara-access-test-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("access.json");
        std::fs::write(&path, r#"{"server":"vpn.example.com:23947","token":"tok"}"#).unwrap();
        let c = ClientConfig {
            server: None,
            network: Some("n".into()),
            secret: Some("s".into()),
            access: Some(path),
            ..Default::default()
        };
        let r = c.validate().unwrap();
        assert_eq!(r.server_host, "vpn.example.com");
        assert_eq!(r.server_port, 23947);
        assert_eq!(r.access_token, "tok");
        std::fs::remove_dir_all(&dir).ok();
    }
}
